"use client"

import * as React from "react"
import { LayoutGridIcon } from "lucide-react"
import { canvasHeight, colPitch, gridToPixel, rowPitch, spanToPixels } from "rud-dashboard"
import type { GridConfig, GridFrame, GridStyle, SerializedItem } from "rud-dashboard"

import { cn } from "@/lib/utils"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { TooltipProvider } from "@/components/ui/tooltip"

import { DashboardItem } from "./dashboard-item"
import { DashboardToolbar } from "./dashboard-toolbar"
import { DashboardWidgetBar } from "./dashboard-widget-bar"
import { useDashboard } from "./use-dashboard"
import type { DashboardApi, WidgetCatalog } from "./use-dashboard"

export interface DashboardProps {
  /** Every widget kind this dashboard can render, keyed by `type`. */
  widgets: WidgetCatalog
  /** Controlled layout. Pair with `onLayoutChange`. */
  layout?: SerializedItem[]
  /** Initial layout for uncontrolled use. */
  defaultLayout?: SerializedItem[]
  onLayoutChange?: (items: SerializedItem[]) => void
  /** Controlled edit mode. */
  editing?: boolean
  defaultEditing?: boolean
  onEditingChange?: (editing: boolean) => void
  /** Set false to lock the layout and hide the edit affordances entirely. */
  editable?: boolean
  /** Canvas background treatment. */
  gridStyle?: GridStyle
  /** Override grid geometry — columns, rowHeight, gap, padding, span limits. */
  grid?: Partial<GridConfig>
  /**
   * Cap the canvas height, in px. The toolbar's "Limit height" switch turns this
   * on; without it that switch falls back to 2.5x the minimum height.
   */
  maxHeight?: number
  /**
   * What the cap does.
   *
   * `scroll` (default) — the canvas stops growing and scrolls; widgets may sit
   * below the fold.
   * `clamp` — the grid is limited to the rows that fit, so nothing can be placed
   * out of sight. Drag, the drop indicator, and keyboard nudges all respect it.
   */
  maxHeightMode?: "scroll" | "clamp"
  /**
   * `false` hides the toolbar. A function replaces it, receiving the same api
   * the built-in toolbar uses.
   */
  toolbar?: boolean | ((api: DashboardApi) => React.ReactNode)
  /** Extra controls rendered at the end of the built-in toolbar. */
  toolbarActions?: React.ReactNode
  /** Replaces the default empty state. */
  emptyState?: React.ReactNode
  className?: string
}

/**
 * Canvas background, drawn from the same frame the layout engine uses — so the
 * guides always line up with where widgets actually land, at any width.
 */
function GridBackground({ style, frame }: { style: GridStyle; frame: GridFrame }) {
  if (style === "none") return null

  const cell = `${colPitch(frame)}px ${rowPitch(frame)}px`
  const origin = `${frame.padding}px ${frame.padding}px`
  const common = "pointer-events-none absolute inset-0 text-muted-foreground"

  if (style === "dots") {
    return (
      <div
        aria-hidden="true"
        className={cn(common, "opacity-40")}
        style={{
          backgroundImage: "radial-gradient(currentColor 1px, transparent 1px)",
          backgroundSize: cell,
          backgroundPosition: origin,
        }}
      />
    )
  }

  return (
    <div
      aria-hidden="true"
      className={cn(common, style === "bold" ? "opacity-25" : "opacity-10")}
      style={{
        backgroundImage:
          "linear-gradient(to right, currentColor 1px, transparent 1px), linear-gradient(to bottom, currentColor 1px, transparent 1px)",
        backgroundSize: cell,
        backgroundPosition: origin,
      }}
    />
  )
}

export function Dashboard({
  widgets,
  layout,
  defaultLayout,
  onLayoutChange,
  editing,
  defaultEditing,
  onEditingChange,
  editable = true,
  gridStyle: gridStyleProp,
  grid: gridOverrides,
  maxHeight,
  maxHeightMode,
  toolbar = true,
  toolbarActions,
  emptyState,
  className,
}: DashboardProps) {
  const api = useDashboard({
    widgets,
    layout,
    defaultLayout,
    onLayoutChange,
    editing,
    defaultEditing,
    onEditingChange,
    grid: gridOverrides,
    maxHeight,
    maxHeightMode,
  })

  const {
    items,
    isEditing,
    metrics,
    grid,
    preview,
    activeId,
    float,
    isFixedHeight,
    isAddWidgetMode,
    isMeasured,
    canvasRef,
    setEditing,
    toggleAddWidgetMode,
    addWidget,
    removeWidget,
    tidy,
    nudge,
    toggleFixedHeight,
    beginDrag,
    beginResize,
  } = api

  const [gridStyle, setGridStyle] = React.useState<GridStyle>(gridStyleProp ?? "lines")
  React.useEffect(() => {
    if (gridStyleProp) setGridStyle(gridStyleProp)
  }, [gridStyleProp])

  const renderBody = (item: SerializedItem) => {
    const definition = widgets[item.type]
    if (!definition) {
      return (
        <p className="text-muted-foreground text-sm">
          No widget registered for type <code className="font-mono">{item.type}</code>.
        </p>
      )
    }
    return definition.render({
      id: item.id,
      type: item.type,
      title: item.title,
      size: { w: item.w, h: item.h },
      isEditing,
    })
  }

  return (
    <TooltipProvider>
      <div
        data-slot="dashboard"
        data-editing={isEditing || undefined}
        className={cn("flex w-full flex-col gap-3", className)}
      >
        {toolbar === true && (
          <DashboardToolbar
            itemCount={items.length}
            isEditing={isEditing}
            editable={editable}
            onEditingChange={setEditing}
            isAddWidgetMode={isAddWidgetMode}
            onToggleAddWidgetMode={toggleAddWidgetMode}
            onTidy={tidy}
            gridStyle={gridStyle}
            onGridStyleChange={setGridStyle}
            isFixedHeight={isFixedHeight}
            onFixedHeightChange={toggleFixedHeight}
          >
            {toolbarActions}
          </DashboardToolbar>
        )}
        {typeof toolbar === "function" && toolbar(api)}

        {toolbar === true && isAddWidgetMode && (
          <DashboardWidgetBar widgets={widgets} onAddWidget={addWidget} />
        )}

        <div
          ref={canvasRef}
          data-slot="dashboard-canvas"
          data-editing={isEditing || undefined}
          className={cn(
            "group/canvas bg-card/40 relative w-full rounded-xl border transition-colors",
            isEditing && "border-primary/30 bg-primary/[0.02]",
            // Only scroll when the content genuinely exceeds the cap; a capped
            // canvas that happens to fit should not show a scrollbar.
            metrics.scrolls ? "overflow-auto" : "overflow-hidden",
            activeId && "touch-none select-none"
          )}
          style={{
            height: metrics.height,
            minHeight: grid.minHeight,
          }}
        >
          <GridBackground style={gridStyle} frame={metrics.frame} />

          {/*
            Nothing renders until the canvas has been measured once.

            Column width is only known after layout, so the very first render
            has a placeholder 1px-wide frame. Painting widgets at that size and
            letting them animate outward produced a visible snap on every load,
            and charts measured themselves against the placeholder. One frame of
            nothing is far better than one frame of wrong.
          */}
          {isMeasured && (
            <div
              className="relative motion-safe:animate-in motion-safe:fade-in motion-safe:duration-200"
              style={{ height: canvasHeight(metrics.rows, metrics.frame) }}
            >
              {items.map((item) => (
                <DashboardItem
                  key={item.id}
                  item={item}
                  frame={metrics.frame}
                  isEditing={isEditing}
                  isActive={activeId === item.id}
                  float={activeId === item.id ? float : null}
                  onRemove={removeWidget}
                  onDragStart={beginDrag}
                  onResizeStart={beginResize}
                  onNudge={nudge}
                >
                  {renderBody(item)}
                </DashboardItem>
              ))}

              {/* Drop indicator: shows where the gesture will land. */}
              {preview && (
                <div
                  aria-hidden="true"
                  data-slot="dashboard-preview"
                  className="border-primary bg-primary/10 pointer-events-none absolute top-0 left-0 z-20 rounded-xl border-2 border-dashed"
                  style={(() => {
                    const at = gridToPixel(preview.x, preview.y, metrics.frame)
                    const size = spanToPixels(preview.w, preview.h, metrics.frame)
                    return {
                      translate: `${at.x}px ${at.y}px`,
                      width: size.width,
                      height: size.height,
                    }
                  })()}
                />
              )}

              {items.length === 0 &&
                (emptyState ?? (
                  <Empty className="absolute inset-0">
                    <EmptyHeader>
                      <EmptyMedia variant="icon">
                        <LayoutGridIcon />
                      </EmptyMedia>
                      <EmptyTitle className="text-balance">No widgets yet</EmptyTitle>
                      <EmptyDescription className="text-pretty">
                        {isEditing
                          ? "Use “Add widget” to place your first one."
                          : editable
                            ? "Choose “Edit layout” to start building."
                            : "This dashboard is empty."}
                      </EmptyDescription>
                    </EmptyHeader>
                  </Empty>
                ))}
            </div>
          )}
        </div>
      </div>
    </TooltipProvider>
  )
}

export { useDashboard }
export type { DashboardApi, WidgetCatalog, WidgetDefinition, WidgetRenderContext } from "./use-dashboard"

"use client"

import * as React from "react"
import { GripVerticalIcon, XIcon } from "lucide-react"
import { gridToPixel, spanToPixels } from "rud-dashboard"
import type { GridFrame, GridRect, ResizeHandle } from "rud-dashboard"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"

/**
 * Resize affordances. Corners show a dot on hover; edges are invisible hit strips.
 *
 * The dots sit 8–16px inside each corner, which is further in than the card's
 * 12px padding — so rather than move them, the card makes room: on hover the
 * header and content ease their padding outward (see `INSET_ON_HOVER` below) and
 * the dots land in the gap that opens up. The mark stays in one place and never
 * covers a chart or a line of text.
 *
 * 24px hit area rather than the usual 40px minimum: a one-column widget is only
 * ~64px wide, so 40px corners would overlap each other, and overlapping hit
 * areas are worse than small ones. Keyboard resize (shift + arrows) is the
 * accessible path.
 */
/**
 * The inset that opens up in edit mode, freeing the corners for the resize dots.
 * Applied to the header and the content so the whole inside draws in together —
 * it reads as the card growing a frame, not as text jumping.
 *
 * Only `padding` transitions. That does reflow the content box, so two guards
 * apply below: it is skipped on cards too small to spare the room, and the
 * transition is dropped while a gesture is running so it never animates a reflow
 * on top of a resize.
 */
const INSET = "group-hover/item:px-5 group-focus-visible/item:px-5"
const INSET_Y = "group-hover/item:py-5 group-focus-visible/item:py-5"
const INSET_TRANSITION =
  "motion-safe:transition-[padding] motion-safe:duration-200 " +
  "motion-safe:ease-[cubic-bezier(0.2,0,0,1)]"

/**
 * Below this the inset would eat the content area rather than frame it — a
 * 1x1 cell is only ~64x56px, and 20px of padding leaves almost nothing.
 */
const MIN_WIDTH_FOR_INSET = 170
const MIN_HEIGHT_FOR_INSET = 130

const HANDLES: { handle: ResizeHandle; className: string; corner: boolean }[] = [
  { handle: "nw", className: "top-0 left-0 size-6 cursor-nwse-resize", corner: true },
  { handle: "ne", className: "top-0 right-0 size-6 cursor-nesw-resize", corner: true },
  { handle: "sw", className: "bottom-0 left-0 size-6 cursor-nesw-resize", corner: true },
  { handle: "se", className: "bottom-0 right-0 size-6 cursor-nwse-resize", corner: true },
  { handle: "n", className: "top-0 inset-x-6 h-2 cursor-ns-resize", corner: false },
  { handle: "s", className: "bottom-0 inset-x-6 h-2 cursor-ns-resize", corner: false },
  { handle: "w", className: "left-0 inset-y-6 w-2 cursor-ew-resize", corner: false },
  { handle: "e", className: "right-0 inset-y-6 w-2 cursor-ew-resize", corner: false },
]

export interface DashboardItemProps {
  item: GridRect & { type: string; title: string }
  frame: GridFrame
  isEditing: boolean
  /** This item is the one currently being dragged or resized. */
  isActive: boolean
  /**
   * Pixel position to paint at while this card is being dragged, overriding its
   * grid position. `snapping: false` means the pointer is moving fast and the
   * card should track it exactly, with no transition to lag behind.
   */
  float?: { x: number; y: number; snapping: boolean } | null
  onRemove?: (id: string) => void
  onDragStart?: (event: React.PointerEvent<HTMLElement>, item: GridRect) => void
  onResizeStart?: (event: React.PointerEvent<HTMLElement>, item: GridRect, handle: ResizeHandle) => void
  onNudge?: (id: string, delta: { x?: number; y?: number; w?: number; h?: number }) => void
  children?: React.ReactNode
}

function DashboardItemComponent({
  item,
  frame,
  isEditing,
  isActive,
  float,
  onRemove,
  onDragStart,
  onResizeStart,
  onNudge,
  children,
}: DashboardItemProps) {
  const slot = gridToPixel(item.x, item.y, frame)
  const size = spanToPixels(item.w, item.h, frame)

  /**
   * Only inset cards with room to spare, and hold the transition still during a
   * gesture: resizing already changes the box every frame, and animating padding
   * at the same time makes charts re-measure repeatedly and look like they are
   * fighting the pointer.
   */
  const canInset =
    isEditing && size.width >= MIN_WIDTH_FOR_INSET && size.height >= MIN_HEIGHT_FOR_INSET
  const insetClasses = canInset && [INSET, !isActive && INSET_TRANSITION]

  // While held, the card paints where the pointer is rather than in its slot.
  const isHeld = Boolean(float)
  const position = float ?? slot
  // Tracking the pointer must be instantaneous; settling into a slot should ease.
  const freeMoving = isHeld && !float!.snapping

  /**
   * Arrow keys move; Shift+arrows resize. Without this the grid is entirely
   * unusable without a pointer — the previous version offered no keyboard path
   * to move or resize a widget at all.
   */
  const handleKeyDown = (event: React.KeyboardEvent<HTMLElement>) => {
    if (!isEditing || !onNudge) return
    const resizing = event.shiftKey
    const deltas: Record<string, { x?: number; y?: number; w?: number; h?: number }> = resizing
      ? {
          ArrowLeft: { w: -1 },
          ArrowRight: { w: 1 },
          ArrowUp: { h: -1 },
          ArrowDown: { h: 1 },
        }
      : {
          ArrowLeft: { x: -1 },
          ArrowRight: { x: 1 },
          ArrowUp: { y: -1 },
          ArrowDown: { y: 1 },
        }

    const delta = deltas[event.key]
    if (!delta) return
    event.preventDefault()
    onNudge(item.id, delta)
  }

  return (
    <Card
      data-slot="dashboard-item"
      data-editing={isEditing || undefined}
      data-active={isActive || undefined}
      role="group"
      aria-label={item.title || item.type}
      tabIndex={isEditing ? 0 : -1}
      onKeyDown={handleKeyDown}
      className={cn(
        "group/item absolute top-0 left-0 gap-0 overflow-hidden py-0",
        "focus-visible:ring-ring/50 focus-visible:ring-[3px] focus-visible:outline-none",
        // Never `transition-all`: it would animate colour, border, and layout
        // properties we never change, and fights the pointer during a drag.
        // Mutually exclusive with the free-moving case below rather than
        // overridden with `!important` — Tailwind v4 spells that as a `!`
        // suffix, and `!transition-none` silently does nothing.
        !freeMoving && [
          "motion-safe:transition-[translate,width,height,box-shadow,opacity,scale]",
          "motion-safe:duration-200 motion-safe:ease-[cubic-bezier(0.2,0,0,1)]",
        ],
        // Tracking a fast pointer: any transition here reads as lag or rubber
        // banding. Only the settle back into a slot animates.
        freeMoving && "transition-none will-change-transform",
        isEditing && "cursor-grab active:cursor-grabbing",
        // Held: lifted above the grid, tracking the pointer. It must not
        // intercept pointer events — the gesture is handled on window.
        isHeld && "pointer-events-none z-30 scale-[1.02] shadow-xl",
        // Resizing keeps the card in place; fade it so the indicator reads.
        isActive && !isHeld && "pointer-events-none opacity-40 transition-none"
      )}
      style={{
        // Position via `translate` rather than left/top: the compositor can
        // animate it without a layout pass on every frame of a drag.
        translate: `${position.x}px ${position.y}px`,
        width: size.width,
        height: size.height,
      }}
      onPointerDown={(event) => {
        if (!isEditing) return
        // Ignore presses that started on a control or a resize handle.
        if ((event.target as HTMLElement).closest("[data-no-drag]")) return
        if (event.button !== 0) return
        onDragStart?.(event, item)
      }}
    >
      {/*
        Two things here are load-bearing:

        `relative z-20` — the corner resize handles are absolutely positioned
        over the whole card, so without it the `ne` handle sits on top of the
        remove button and swallows its clicks.

        No `flex` — `CardHeader` is a grid and `CardAction` right-aligns itself
        with `col-start-2`. Switching to flex silently breaks that and the remove
        button ends up jammed against the title. Only padding, gap, and
        alignment are overridden.
      */}
      <CardHeader
        className={cn(
          "relative z-20 shrink-0 items-center gap-0 border-b px-3 py-2",
          insetClasses
        )}
      >
        <CardTitle className="flex min-w-0 items-center gap-1.5 text-sm">
          {isEditing && (
            <GripVerticalIcon
              className="text-muted-foreground/60 size-3.5 shrink-0"
              aria-hidden="true"
            />
          )}
          <span className="truncate">{item.title}</span>
        </CardTitle>
        {isEditing && onRemove && (
          <CardAction data-no-drag>
            <Button
              variant="ghost"
              size="icon"
              aria-label={`Remove ${item.title || item.type}`}
              onClick={() => onRemove(item.id)}
              // Visually 24px to fit the compact header, but the pseudo-element
              // extends the hit area to 40px so it is comfortable to tap.
              className={cn(
                "text-muted-foreground hover:text-destructive relative size-6",
                "after:absolute after:top-1/2 after:left-1/2 after:size-10",
                "after:-translate-x-1/2 after:-translate-y-1/2 after:content-['']"
              )}
            >
              <XIcon />
            </Button>
          </CardAction>
        )}
      </CardHeader>

      <CardContent
        className={cn(
          "min-h-0 flex-1 overflow-auto p-3",
          insetClasses,
          // Vertical too, so the bottom corners are clear as well.
          canInset && INSET_Y
        )}
      >
        {children}
      </CardContent>

      {isEditing &&
        HANDLES.map(({ handle, className, corner }) => (
          <div
            key={handle}
            data-no-drag
            aria-hidden="true"
            onPointerDown={(event) => {
              event.stopPropagation()
              if (event.button !== 0) return
              onResizeStart?.(event, item, handle)
            }}
            className={cn(
              "absolute z-10 touch-none",
              className,
              corner && [
                "after:bg-primary after:absolute after:inset-2 after:rounded-full",
                "after:opacity-0 after:transition-opacity after:duration-200",
                // Scoped to this item: hinting on every widget at once whenever the
                // pointer is anywhere in the canvas is just noise.
                "group-hover/item:after:opacity-40 group-focus-visible/item:after:opacity-60",
                "hover:after:opacity-100",
              ]
            )}
          />
        ))}
    </Card>
  )
}

/**
 * Re-render only when something visible actually changes. A dashboard re-renders
 * on every pointer move during a drag, so every other widget must bail out.
 */
export const DashboardItem = React.memo(
  DashboardItemComponent,
  (prev, next) =>
    prev.item.id === next.item.id &&
    prev.item.x === next.item.x &&
    prev.item.y === next.item.y &&
    prev.item.w === next.item.w &&
    prev.item.h === next.item.h &&
    prev.item.title === next.item.title &&
    prev.isEditing === next.isEditing &&
    prev.isActive === next.isActive &&
    prev.float === next.float &&
    prev.frame === next.frame &&
    prev.children === next.children
)

"use client"

import * as React from "react"
import {
  DEFAULT_GRID,
  applyResize,
  clamp,
  findFreeSlot,
  gridToPixel,
  measureGrid,
  nextItemId,
  packItems,
  parseLayout,
  pixelToGrid,
  reflow,
  resolveColumns,
  resolveFrame,
  resolveCollisions,
  serializeLayout,
} from "rud-dashboard"
import type {
  DashboardItem,
  GridConfig,
  GridMetrics,
  GridRect,
  ResizeHandle,
  SerializedItem,
  SerializedLayout,
} from "rud-dashboard"

/** How to render one kind of widget, and how it should appear in the palette. */
export interface WidgetDefinition {
  /** Shown in the item header and in the palette. */
  title: string
  /** Shown in the palette only. */
  description?: string
  /**
   * Any icon component. Rendered with no props and sized by CSS, so the type
   * only has to say "a component that needs no props".
   *
   * Deliberately not `ComponentType<{ className?: string }>`: under Preact,
   * `className` is `Signalish<string>` rather than `string`, so naming the prop
   * here makes every `lucide-react` icon fail to typecheck on Preact. Widening
   * it is the whole of the Preact compatibility story for this file.
   */
  icon?: React.ElementType
  /** Span used when added from the palette. Defaults to 4x3. */
  defaultSize?: { w: number; h: number }
  /**
   * A miniature of the widget, shown in the add-widget bar.
   *
   * Far more useful than a name and an icon — you can see what you are about to
   * place. Keep it cheap and static; it renders once per palette entry.
   */
  preview?: () => React.ReactNode
  /** Renders the widget body. */
  render: (context: WidgetRenderContext) => React.ReactNode
}

export interface WidgetRenderContext {
  id: string
  type: string
  title: string
  /** Current span in grid cells — useful for switching density. */
  size: { w: number; h: number }
  isEditing: boolean
}

/** Every widget kind the dashboard can render, keyed by `type`. */
export type WidgetCatalog = Record<string, WidgetDefinition>

/**
 * Value-equality for metrics.
 *
 * `measureGrid` builds a fresh object every pass, so storing its result
 * unconditionally changes `metrics.frame` by identity even when the numbers are
 * unchanged. That re-renders every widget on any measure — and re-mounting a
 * chart mid-animation leaves its bars stuck at zero height. Keeping the old
 * object when nothing moved makes the memo on `DashboardItem` actually work.
 */
function sameMetrics(a: GridMetrics, b: GridMetrics): boolean {
  return (
    a.width === b.width &&
    a.height === b.height &&
    a.cols === b.cols &&
    a.rows === b.rows &&
    a.scrolls === b.scrolls &&
    a.frame.columns === b.frame.columns &&
    a.frame.colWidth === b.frame.colWidth &&
    a.frame.rowHeight === b.frame.rowHeight &&
    a.frame.gap === b.frame.gap &&
    a.frame.padding === b.frame.padding
  )
}

/**
 * Pointer speed, in px/ms, above which a dragged card stops snapping and just
 * follows the pointer.
 *
 * ~0.35 px/ms is roughly 350px/s — a deliberate throw rather than a careful
 * placement. Below it the card is being positioned, so it snaps.
 */
const FREE_MOVE_SPEED = 0.35

/** How long the pointer must hold still before a free-moving card settles. */
const SETTLE_DELAY_MS = 90

/** Smoothing on the speed estimate. Raw per-event deltas are far too jittery. */
const SPEED_SMOOTHING = 0.4

/** An in-flight pointer gesture. */
type Gesture =
  | {
      kind: "drag"
      id: string
      /** Pointer offset inside the card at grab time, in px. */
      grabPxX: number
      grabPxY: number
    }
  | { kind: "resize"; id: string; handle: ResizeHandle; startX: number; startY: number; origin: GridRect }

/**
 * Where a dragged card is actually painted.
 *
 * While the pointer is moving quickly the card renders at `x`/`y` directly, so
 * it tracks the cursor 1:1 instead of stepping between cells. Once the pointer
 * slows or stops, `snapping` flips true and the card eases into the slot the
 * drop indicator is showing. Snapping on every move is what made dragging feel
 * like it was catching on something.
 */
export interface DragFloat {
  x: number
  y: number
  snapping: boolean
}

export interface UseDashboardOptions {
  widgets: WidgetCatalog
  layout?: SerializedItem[]
  defaultLayout?: SerializedItem[]
  onLayoutChange?: (items: SerializedItem[]) => void
  editing?: boolean
  defaultEditing?: boolean
  onEditingChange?: (editing: boolean) => void
  grid?: Partial<GridConfig>
  /**
   * Cap the canvas height, in px. Omit to grow with the content.
   *
   * The toolbar's "Limit height" switch turns this on and off; without it, that
   * switch falls back to a default of `2.5x` the minimum height.
   */
  maxHeight?: number
  /** `scroll` (default) caps the box and scrolls; `clamp` limits the grid rows. */
  maxHeightMode?: "scroll" | "clamp"
}

/**
 * Support both controlled and uncontrolled use with one hook, the way native
 * inputs do. The previous API needed three overlapping mechanisms for this
 * (`initialItems`, `onItemsChange`, and an optional external `controller`),
 * which meant the source of truth depended on which props you happened to pass.
 */
function useControllableState<T>(
  controlled: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void
): [T, (next: T | ((prev: T) => T)) => void] {
  const isControlled = controlled !== undefined
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue)
  const value = isControlled ? controlled : uncontrolled

  // Keep the latest callback in a ref so `setValue` stays referentially stable.
  const onChangeRef = React.useRef(onChange)
  React.useEffect(() => {
    onChangeRef.current = onChange
  })

  const valueRef = React.useRef(value)
  valueRef.current = value

  const setValue = React.useCallback(
    (next: T | ((prev: T) => T)) => {
      const resolved =
        typeof next === "function" ? (next as (prev: T) => T)(valueRef.current) : next
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled]
  )

  return [value, setValue]
}

export function useDashboard({
  widgets,
  layout,
  defaultLayout,
  onLayoutChange,
  editing,
  defaultEditing = false,
  onEditingChange,
  grid: gridOverrides,
  maxHeight,
  maxHeightMode = "scroll",
}: UseDashboardOptions) {
  const grid = React.useMemo<GridConfig>(
    () => ({ ...DEFAULT_GRID, ...gridOverrides }),
    [gridOverrides]
  )

  const [items, setItems] = useControllableState<SerializedItem[]>(
    layout,
    // Normalise the initial layout once, so a malformed saved payload cannot
    // crash the first render.
    React.useMemo(() => parseLayout({ version: 1, items: defaultLayout ?? [] }).layout.items, []),
    onLayoutChange
  )
  const [isEditing, setEditing] = useControllableState(editing, defaultEditing, onEditingChange)

  const canvasRef = React.useRef<HTMLDivElement>(null)
  const [metrics, setMetricsState] = React.useState<GridMetrics>(() => ({
    frame: resolveFrame(0, grid),
    width: 0,
    height: grid.minHeight,
    cols: resolveColumns(0, grid.columns),
    rows: 1,
    scrolls: false,
  }))

  /** Only commit metrics that actually differ, preserving object identity. */
  const setMetrics = React.useCallback((next: GridMetrics) => {
    setMetricsState((current) => (sameMetrics(current, next) ? current : next))
  }, [])
  const [heightCapped, setHeightCapped] = React.useState(false)
  /** The cap actually in force: null means "grow with the content". */
  const heightCap = heightCapped ? (maxHeight ?? Math.round(grid.minHeight * 2.5)) : null
  const [isAddWidgetMode, setAddWidgetMode] = React.useState(false)
  const [gesture, setGesture] = React.useState<Gesture | null>(null)
  const [preview, setPreview] = React.useState<GridRect | null>(null)
  const [float, setFloat] = React.useState<DragFloat | null>(null)

  // Pointer-speed tracking for the free-move behaviour above.
  const lastMoveRef = React.useRef<{ x: number; y: number; t: number } | null>(null)
  const speedRef = React.useRef(0)
  const settleTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null)
  /** Latest snapped pixel position, so the settle timer needs no pointer event. */
  const snappedPxRef = React.useRef({ x: 0, y: 0 })

  // Mirrors of the latest values, so effects and callbacks can read "now"
  // without re-subscribing on every change.
  const itemsRef = React.useRef(items)
  itemsRef.current = items
  const metricsRef = React.useRef(metrics)
  metricsRef.current = metrics
  const previewRef = React.useRef(preview)
  previewRef.current = preview
  /**
   * In `clamp` mode nothing may be placed below the last visible row — that is
   * the whole point of the mode, so gestures have to respect it too.
   */
  const clampRowsRef = React.useRef(false)
  clampRowsRef.current = heightCap !== null && maxHeightMode === "clamp"

  /* ------------------------------- measuring ------------------------------ */

  React.useEffect(() => {
    const element = canvasRef.current
    if (!element) return

    const measure = () => {
      const width = element.clientWidth
      if (width === 0) return

      const previousCols = metricsRef.current.cols
      const nextCols = resolveColumns(width, grid.columns)

      // Reflow before measuring rows, so the height accounts for the new layout.
      if (nextCols !== previousCols && itemsRef.current.length > 0) {
        const reflowed = reflow(itemsRef.current, {
          fromCols: previousCols,
          toCols: nextCols,
          minSpan: grid.minSpan,
        })
        setItems(reflowed as SerializedItem[])
        setMetrics(measureGrid(width, reflowed, grid, { maxHeight: heightCap, maxHeightMode }))
      } else {
        setMetrics(measureGrid(width, itemsRef.current, grid, { maxHeight: heightCap, maxHeightMode }))
      }
    }

    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [grid, heightCap, maxHeightMode, setItems, setMetrics])

  // Keep the canvas height in step with the items themselves.
  React.useEffect(() => {
    const width = metricsRef.current.width
    if (width > 0) setMetrics(measureGrid(width, items, grid, { maxHeight: heightCap, maxHeightMode }))
  }, [items, grid, heightCap, maxHeightMode, setMetrics])

  /* ------------------------------- gestures ------------------------------- */

  /** Pointer position relative to the canvas box, in px. */
  const pointerToCanvas = React.useCallback((event: PointerEvent | React.PointerEvent<HTMLElement>) => {
    const rect = canvasRef.current?.getBoundingClientRect()
    if (!rect) return null
    return { x: event.clientX - rect.left, y: event.clientY - rect.top }
  }, [])

  const beginDrag = React.useCallback(
    (event: React.PointerEvent<HTMLElement>, item: GridRect) => {
      if (!isEditing) return
      const point = pointerToCanvas(event)
      if (!point) return

      // Grab offset in pixels, not cells: the card has to follow the pointer
      // without jumping to align its corner under the cursor.
      const at = gridToPixel(item.x, item.y, metricsRef.current.frame)
      setGesture({
        kind: "drag",
        id: item.id,
        grabPxX: point.x - at.x,
        grabPxY: point.y - at.y,
      })
      setPreview({ ...item })
      setFloat({ x: at.x, y: at.y, snapping: true })
      snappedPxRef.current = { x: at.x, y: at.y }
      lastMoveRef.current = { x: point.x, y: point.y, t: event.timeStamp }
      speedRef.current = 0
    },
    [isEditing, pointerToCanvas]
  )

  const beginResize = React.useCallback(
    (event: React.PointerEvent<HTMLElement>, item: GridRect, handle: ResizeHandle) => {
      if (!isEditing) return
      const point = pointerToCanvas(event)
      if (!point) return
      const cell = pixelToGrid(point.x, point.y, metricsRef.current.frame)
      setGesture({
        kind: "resize",
        id: item.id,
        handle,
        startX: cell.x,
        startY: cell.y,
        origin: { ...item },
      })
      setPreview({ ...item })
    },
    [isEditing, pointerToCanvas]
  )

  // A single pointer-event pipeline. The previous implementation bound
  // `onTouchStart` but only ever listened for `mousemove`/`mouseup`, so a touch
  // drag would start, show a preview, and then never move or commit. Pointer
  // events cover mouse, touch, and pen in one path.
  React.useEffect(() => {
    if (!gesture) return

    const handleMove = (event: PointerEvent) => {
      const point = pointerToCanvas(event)
      if (!point) return
      const { cols, rows, frame } = metricsRef.current

      // Smoothed pointer speed, in px/ms.
      const previous = lastMoveRef.current
      if (previous) {
        const dt = Math.max(1, event.timeStamp - previous.t)
        const distance = Math.hypot(point.x - previous.x, point.y - previous.y)
        speedRef.current =
          speedRef.current * (1 - SPEED_SMOOTHING) + (distance / dt) * SPEED_SMOOTHING
      }
      lastMoveRef.current = { x: point.x, y: point.y, t: event.timeStamp }

      // The drop indicator always snaps: it is what tells you where this lands.
      const cell = pixelToGrid(
        gesture.kind === "drag" ? point.x - gesture.grabPxX : point.x,
        gesture.kind === "drag" ? point.y - gesture.grabPxY : point.y,
        frame
      )

      if (gesture.kind === "drag") {
        const held = previewRef.current
        const span = held?.w ?? 1
        const spanH = held?.h ?? 1
        const maxY = clampRowsRef.current ? Math.max(0, rows - spanH) : Number.POSITIVE_INFINITY
        const targetCell = {
          x: clamp(cell.x, 0, Math.max(0, cols - span)),
          y: clamp(cell.y, 0, maxY),
        }
        // Remembered so the settle timer can snap without a pointer event.
        snappedPxRef.current = gridToPixel(targetCell.x, targetCell.y, frame)

        if (speedRef.current > FREE_MOVE_SPEED) {
          // Moving fast: track the pointer exactly.
          setFloat({ x: point.x - gesture.grabPxX, y: point.y - gesture.grabPxY, snapping: false })
        } else {
          // Slow enough to be placing it: sit in the slot the indicator shows.
          setFloat({ ...snappedPxRef.current, snapping: true })
        }

        // Hold still and it settles, even though no more pointermove events come.
        if (settleTimerRef.current) clearTimeout(settleTimerRef.current)
        settleTimerRef.current = setTimeout(() => {
          speedRef.current = 0
          setFloat({ ...snappedPxRef.current, snapping: true })
        }, SETTLE_DELAY_MS)
      }

      setPreview((current) => {
        if (!current) return current

        if (gesture.kind === "drag") {
          const limitY = clampRowsRef.current
            ? Math.max(0, rows - current.h)
            : Number.POSITIVE_INFINITY
          return {
            ...current,
            x: clamp(cell.x, 0, Math.max(0, cols - current.w)),
            y: clamp(cell.y, 0, limitY),
          }
        }

        return {
          ...current,
          ...applyResize(
            gesture.origin,
            gesture.handle,
            cell.x - gesture.startX,
            cell.y - gesture.startY,
            { cols, rows: Math.max(rows, gesture.origin.y + grid.maxSpan), minSpan: grid.minSpan, maxSpan: grid.maxSpan }
          ),
        }
      })
    }

    const finish = () => {
      const committed = previewRef.current
      const activeId = gesture.id

      if (committed) {
        const updated = itemsRef.current.map((item) =>
          item.id === activeId
            ? {
                ...item,
                x: committed.x,
                y: committed.y,
                w: committed.w,
                h: committed.h,
                // The user chose this spot: make it the anchor to return to.
                anchorX: committed.x,
                anchorY: committed.y,
                anchorW: committed.w,
                anchorH: committed.h,
              }
            : item
        )
        setItems(
          resolveCollisions(updated, {
            cols: metricsRef.current.cols,
            minSpan: grid.minSpan,
            pinnedId: activeId,
          }) as SerializedItem[]
        )
      }

      if (settleTimerRef.current) clearTimeout(settleTimerRef.current)
      settleTimerRef.current = null
      lastMoveRef.current = null
      speedRef.current = 0

      setGesture(null)
      setPreview(null)
      setFloat(null)
    }

    window.addEventListener("pointermove", handleMove)
    window.addEventListener("pointerup", finish)
    window.addEventListener("pointercancel", finish)
    return () => {
      window.removeEventListener("pointermove", handleMove)
      window.removeEventListener("pointerup", finish)
      window.removeEventListener("pointercancel", finish)
      if (settleTimerRef.current) clearTimeout(settleTimerRef.current)
    }
  }, [gesture, grid, pointerToCanvas, setItems])

  /* -------------------------------- actions ------------------------------- */

  const addWidget = React.useCallback(
    (type: string) => {
      const definition = widgets[type]
      if (!definition) return

      const size = definition.defaultSize ?? { w: 4, h: 3 }
      const cols = metricsRef.current.cols
      const id = nextItemId(itemsRef.current)

      const slot = findFreeSlot(
        { id, x: 0, y: 0, w: size.w, h: size.h },
        itemsRef.current,
        { cols, minSpan: grid.minSpan, ignoreAnchor: true, strategy: "compact" }
      )

      setItems([
        ...itemsRef.current,
        {
          id,
          type,
          title: definition.title,
          ...slot,
          anchorX: slot.x,
          anchorY: slot.y,
          anchorW: slot.w,
          anchorH: slot.h,
        },
      ])
    },
    [grid.minSpan, setItems, widgets]
  )

  const removeWidget = React.useCallback(
    (id: string) => {
      setItems(itemsRef.current.filter((item) => item.id !== id))
    },
    [setItems]
  )

  const tidy = React.useCallback(() => {
    setItems(
      packItems(itemsRef.current, {
        cols: metricsRef.current.cols,
        minSpan: grid.minSpan,
      }) as SerializedItem[]
    )
  }, [grid.minSpan, setItems])

  const clear = React.useCallback(() => setItems([]), [setItems])

  /** Move or resize the focused item from the keyboard. */
  const nudge = React.useCallback(
    (id: string, delta: { x?: number; y?: number; w?: number; h?: number }) => {
      const { cols } = metricsRef.current
      const current = itemsRef.current.find((item) => item.id === id)
      if (!current) return

      const w = clamp(current.w + (delta.w ?? 0), grid.minSpan, Math.min(grid.maxSpan, cols))
      const h = clamp(current.h + (delta.h ?? 0), grid.minSpan, grid.maxSpan)
      const x = clamp(current.x + (delta.x ?? 0), 0, Math.max(0, cols - w))
      const maxY = clampRowsRef.current
        ? Math.max(0, metricsRef.current.rows - h)
        : Number.POSITIVE_INFINITY
      const y = clamp(current.y + (delta.y ?? 0), 0, maxY)

      const moved = itemsRef.current.map((item) =>
        item.id === id
          ? { ...item, x, y, w, h, anchorX: x, anchorY: y, anchorW: w, anchorH: h }
          : item
      )
      setItems(
        resolveCollisions(moved, {
          cols,
          minSpan: grid.minSpan,
          pinnedId: id,
        }) as SerializedItem[]
      )
    },
    [grid.maxSpan, grid.minSpan, setItems]
  )

  const toggleAddWidgetMode = React.useCallback(() => {
    setAddWidgetMode((current) => !current)
  }, [])

  const save = React.useCallback(
    (): SerializedLayout => serializeLayout(itemsRef.current as DashboardItem[]),
    []
  )

  const load = React.useCallback(
    (payload: unknown) => {
      const { layout: parsed, warnings } = parseLayout(payload)
      // Always surface these: a dropped item means the stored payload is bad,
      // which is worth knowing in production too. No bundler-specific globals
      // here, so this file works unchanged in Vite, Next.js, and Preact.
      if (warnings.length > 0) {
        console.warn("[dashboard] layout loaded with warnings:", warnings)
      }
      setItems(
        resolveCollisions(parsed.items, {
          cols: metricsRef.current.cols,
          minSpan: grid.minSpan,
        }) as SerializedItem[]
      )
    },
    [grid.minSpan, setItems]
  )

  const toggleFixedHeight = React.useCallback(() => {
    setHeightCapped((current) => !current)
  }, [])

  return {
    // state
    items,
    isEditing,
    metrics,
    grid,
    preview,
    /** Where the dragged card paints; null unless a drag is in flight. */
    float,
    /** False until the canvas has been measured once. */
    isMeasured: metrics.width > 0,
    activeId: gesture?.id ?? null,
    isFixedHeight: heightCapped,
    /** True when the canvas is capped and must scroll to show everything. */
    scrolls: metrics.scrolls,
    isAddWidgetMode: isEditing && isAddWidgetMode,
    canvasRef,
    widgets,
    // actions
    setEditing,
    toggleAddWidgetMode,
    setAddWidgetMode,
    addWidget,
    removeWidget,
    tidy,
    clear,
    nudge,
    save,
    load,
    toggleFixedHeight,
    beginDrag,
    beginResize,
  }
}

export type DashboardApi = ReturnType<typeof useDashboard>

